async function run() {
  const promises = [];
  for (let i = 1; i <= 10; i++) {
    const ip = `1.1.1.${i}`;
    promises.push(
      fetch('http://localhost:3000/poll/colors/vote', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Forwarded-For': ip
        },
        body: JSON.stringify({ optionId: 5 })
      }).then(async (res) => {
        const data = await res.json();
        return { status: res.status, data };
      })
    );
  }

  const results = await Promise.all(promises);
  console.log('Results:', results);

  // Fetch final options for colors poll
  const res = await fetch('http://localhost:3000/poll/colors/');
  const text = await res.text();
  console.log('Does page contain Red vote count of 10?');
  const match = text.match(/<text data-option-id="5"[^>]*>(\d+)<\/text>/);
  if (match) {
    console.log('Vote count in HTML:', match[1]);
  } else {
    console.log('Could not find vote count in HTML');
  }
}

run().catch(console.error);

